    d.out(`G\xF3i: ${plan ?? (unsupported ? "c\u1ED5ng ch\u01B0a c\xF3 endpoint /account \u2014 xem tr\xEAn locaith.ai" : "c\u1ED5ng ch\u01B0a tr\u1EA3 th\xF4ng tin g\xF3i \u2014 xem tr\xEAn locaith.ai")}`);
    if (acct.ok && acct.account.limits?.unlimited) d.out("H\u1EA1n m\u1EE9c: kh\xF4ng gi\u1EDBi h\u1EA1n (giai \u0111o\u1EA1n m\u1EDF, kh\xF4ng thu ph\xED)");
